final_output = (unsigned char *)malloc(total_pixels);
fread(full_image, sizeof(unsigned char), total_pixels, fp_in);
fclose(fp_in);
printf("MPI Master (Rank 0): Image %dx%d loaded across %d processes.\n", width, height,
size);
}
